package org.agentworkbench.intellij

import com.google.gson.JsonParser
import org.agentworkbench.intellij.kit.InspectProtocol
import org.junit.Assert.*
import org.junit.Test

/** Fixtures are generated by the real Kit 2 CLI, including targeted projections. */
class InspectV2ContractTest {
    private fun fixture(name: String) = javaClass.getResourceAsStream("/inspect-v2/$name.json")!!.use { it.readBytes().decodeToString() }

    @Test fun actualProducerResponsesParse() {
        mapOf("workspace" to "workspace", "items" to "items", "task" to "projection", "summary" to "projection",
            "change" to "projection", "flow" to "projection", "document" to "document", "verification" to "verification",
            "handoff" to "handoff", "search" to "search", "workflow" to "workflow", "runs" to "runs").forEach { (name, operation) ->
            val result = InspectProtocol.parse(fixture(name), operation, "/synthetic/kit")
            assertTrue("$name: ${result.exceptionOrNull()}", result.isSuccess)
        }
    }

    @Test fun taskProjectionContainsRoleBasedDocumentsAndSingleCompletionState() {
        val data = JsonParser.parseString(fixture("task")).asJsonObject.getAsJsonObject("data")
        assertTrue(data.getAsJsonArray("documents").any { it.asJsonObject.get("role").asString == "change" })
        val task = data.getAsJsonArray("tasks").first().asJsonObject
        assertEquals("completed", task.get("status").asString)
        assertFalse(task.has("trusted"))
        assertFalse(data.getAsJsonObject("summary").has("trustedProgress"))
    }

    @Test fun oldProtocolIsRejected() {
        val old = JsonParser.parseString(fixture("workspace")).asJsonObject
        old.getAsJsonObject("apiVersion").addProperty("major", 1)
        assertTrue(InspectProtocol.parse(old.toString(), "workspace", "/synthetic/kit").isFailure)
    }

    @Test fun completionComesFromKitInsteadOfLifecycleGuessing() {
        val summary = JsonParser.parseString(fixture("task")).asJsonObject.getAsJsonObject("data").getAsJsonObject("summary")
        assertEquals("active", summary.get("status").asString)
        assertNull(WorkbenchService.completionBlocker(summary))
        summary.getAsJsonObject("completionAction").addProperty("available", false)
        summary.getAsJsonObject("completionAction").addProperty("reason", "仍待外部验收")
        assertEquals("仍待外部验收", WorkbenchService.completionBlocker(summary))
    }

    @Test fun recordedPassDoesNotClaimCurrentCodePass() {
        val data = JsonParser.parseString(fixture("verification")).asJsonObject.getAsJsonObject("data")
        assertEquals("passed", data.get("recordedResult").asString)
        assertEquals("not_checked", data.get("applicability").asString)
    }

    @Test fun blockedAndCancelledItemsExposeReasonsAndCannotComplete() {
        val blocked = JsonParser.parseString(fixture("blocked")).asJsonObject.getAsJsonObject("data").getAsJsonObject("summary")
        assertEquals("等待验收环境", blocked.getAsJsonArray("executionBlockers")[0].asJsonObject.get("reason").asString)
        assertEquals("环境恢复", blocked.getAsJsonArray("executionBlockers")[0].asJsonObject.get("condition").asString)
        assertNotNull(WorkbenchService.completionBlocker(blocked))
        val cancelled = JsonParser.parseString(fixture("cancelled")).asJsonObject.getAsJsonObject("data").getAsJsonObject("summary")
        assertEquals("cancelled", cancelled.get("status").asString)
        assertEquals("目标已被替代", cancelled.getAsJsonObject("cancellation").get("reason").asString)
        assertNotNull(WorkbenchService.completionBlocker(cancelled))
    }
}
